  'commission_plain_service_fixed' => 'This applies to the service portion of each booking (labour and service line items—not spare-parts lines). With fixed commission, the platform takes the same flat amount from every eligible service line. The provider keeps whatever is left of that line after the fee (never below zero). Taxes, discounts, and payment method rules in real bookings may still change the final settlement.',
  'commission_plain_service_tiered' => 'This applies to the service portion of each booking. With tiered commission, you split service line totals into ranges (from / to, or unlimited on top). Each line’s service subtotal falls into exactly one band; that band decides whether the platform takes a percentage of that line or another fixed amount. The provider earns the remainder of that service line. Configure bands so typical job sizes are covered.',
  'commission_plain_spare_fixed' => 'This applies only to spare-parts / product lines when a provider is set up to pay commission on those lines (your operational rules). Fixed commission means the same flat platform fee is taken from each eligible parts line; the provider keeps the rest of that line amount.',
  'commission_plain_spare_tiered' => 'This applies to spare-parts lines when commission on parts is enabled for a provider. Tiered rules work like service: the parts line subtotal is matched to a range, then a percentage or fixed admin fee applies to that line. The provider keeps the remainder of that parts line.',
