  'Also, there is an option to choose a specific date & time to go to maintenance mode.' => 'Also, there is an option to choose a specific date & time to go to maintenance mode.',
  'This address represents the business location from which the admin operates and manages providers, customers, and service personnel.' => 'This address represents the business location from which the admin operates and manages providers, customers, and service personnel.',
  'This logo is the main visual identity of the business. It represents the brand and is usually displayed on the website/app header, login pages, invoices, and promotional materials. The Fav Icon helps users quickly identify the site among multiple open tabs' => 'This logo is the main visual identity of the business. It represents the brand and is usually displayed on the website/app header, login pages, invoices, and promotional materials. The Fav Icon helps users quickly identify the site among multiple open tabs',
  'General Setup is the basic configuration stage where you define essential business settings. This section currently includes Time Zone & Date Format, Pagination Limit, Phone Number Visibility in Chat, and Currency configuration.' => 'General Setup is the basic configuration stage where you define essential business settings. This section currently includes Time Zone & Date Format, Pagination Limit, Phone Number Visibility in Chat, and Currency configuration.',
  'Logo and Fav Icon' => 'Logo and Fav Icon',
  'The Country Name field, when setting up a business is essential for a multitude of reasons, spanning legal, operational, financial, and marketing aspects.' => 'The Country Name field, when setting up a business is essential for a multitude of reasons, spanning legal, operational, financial, and marketing aspects.',
  'A phone number provides customers and providers with a direct and immediate way to reach your business for urgent inquiries, support needs, or quick questions.' => 'A phone number provides customers and providers with a direct and immediate way to reach your business for urgent inquiries, support needs, or quick questions.',
  'A company email system often provides centralised management and archiving of business communication.' => 'A company email system often provides centralised management and archiving of business communication.',
  'The Business name often serves as the primary identifier for your business as a legal entity.' => 'The Business name often serves as the primary identifier for your business as a legal entity.',
  'This is a short message shown on the website to let visitors know that the site uses cookies to collect information and improve their browsing experience' => 'This is a short message shown on the website to let visitors know that the site uses cookies to collect information and improve their browsing experience',
  'Cookies text' => 'Cookies text',
  'This is a short statement that shows your company owns the content on your website. It usually includes the copyright symbol (©), the year, and your company name.' => 'This is a short statement that shows your company owns the content on your website. It usually includes the copyright symbol (©), the year, and your company name.',
  'A commission-based business model allows the platform to earn revenue by charging a predefined percentage amount from each successful transaction completed through the system. The commission is automatically deducted from the order value before the remaining amount is settled with the vendor or service provider.' => 'A commission-based business model allows the platform to earn revenue by charging a predefined percentage amount from each successful transaction completed through the system. The commission is automatically deducted from the order value before the remaining amount is settled with the vendor or service provider.',
  'Use the Server API Key to enable Place API access for backend services, and the Client API Key to enable the Maps JavaScript API for frontend usage.' => 'Use the Server API Key to enable Place API access for backend services, and the Client API Key to enable the Maps JavaScript API for frontend usage.',
  'This section is used to configure Google Map integration for your system. To enable map-based features such as location selection, serviceman tracking, and distance calculation, you must provide valid Google Map API keys.' => 'This section is used to configure Google Map integration for your system. To enable map-based features such as location selection, serviceman tracking, and distance calculation, you must provide valid Google Map API keys.',
  'If SMTP configuration is disabled or incorrect, the system will not be able to send any email notifications.' => 'If SMTP configuration is disabled or incorrect, the system will not be able to send any email notifications.',
  'Enter the mailer name, SMTP host, port, encryption type, username, password, and sender email address based on your email service provider. Once configured, use the Send Test Mail option to verify that emails are working correctly.' => 'Enter the mailer name, SMTP host, port, encryption type, username, password, and sender email address based on your email service provider. Once configured, use the Send Test Mail option to verify that emails are working correctly.',
  'This section allows you to configure SMTP email settings so the system can send emails reliably. By providing valid SMTP credentials, the platform can deliver system notifications, OTPs, password reset emails, booking updates, and other automated messages.' => 'This section allows you to configure SMTP email settings so the system can send emails reliably. By providing valid SMTP credentials, the platform can deliver system notifications, OTPs, password reset emails, booking updates, and other automated messages.',
  'Setup Email Configuration Guideline' => 'Setup Email Configuration Guideline',
