  'WhatsApp_booking_template_help' => 'Set messages for new bookings, status changes, provider reassignment, schedule updates, payments and refunds on bookings, serviceman assignment, and booking verification. When enabled, each non-empty template is sent to that party if a valid phone is available. Use the variables below; they are replaced with live booking data.',
