  'Record existed' => 'Record existed',
  'Special_financial_settlement' => 'Special financial settlement',
  'Financial_settlement_help_intro' => 'Choose the situation that matches this job. Preview updates as you change fields. For most scenarios, save before you change booking status. “Cancel After Visit Decided Charges” uses Save and cancel, and “Job completed — visit / call-out mainly” uses Save and complete, once decided charges are fully collected. For loss-making bookings (customer did not pay full amount), enter amount paid and how the loss is split, then use Save and complete to mark the job complete with the loss-making tag. On the booking details page, special settlement is available while the booking is ongoing — including after a reopen from completed.',
  'Financial_settlement_card_hint' => 'Visit-only earnings, cancel-after-visit, custom commission, loss-making (partial pay / bad debt), or short payment after completion.',
  'Financial_settlement_not_configured' => 'Using normal commission rules for this booking.',
  'Scenario' => 'Scenario',
  'Bfs_label_standard' => 'Standard — full service, normal commission rules',
  'Bfs_label_cancel_keep_visit' => 'Cancel After Visit Decided Charges',
  'Bfs_label_complete_visit_only' => 'Job completed: little or no real service — earn mainly from visit / call-out fee',
  'Bfs_scaled_disabled_when_due_zero' => 'Disabled because Due Balance is 0.',
  'Bfs_label_custom_commission' => 'Custom company commission for this booking only',
  'Bfs_label_scaled_partial_or_bad_debt' => 'Customer did not pay full amount (Loss Making Booking)',
  'Bfs_popover_standard' => '<p><strong>When to use:</strong> Normal job — service delivered and billed as usual.</p><p><strong>Example:</strong> AC service completed; customer pays full invoice; company commission follows your tier/category rules.</p>',
  'Bfs_popover_cancel_keep_visit' => '<p><strong>When to use:</strong> Provider attended but could not perform the booked service (e.g. parts unavailable, not repairable, unsafe).</p><p><strong>What you set:</strong> Visiting charges and optional closing amount <strong>to be paid</strong> by the customer (the new bill), with company and provider amounts on the visit line and closing line (closing defaults from commission tiers).</p><p><strong>Payments:</strong> If anything is still due, record payments below until due is zero.</p><p><strong>Action:</strong> Use <strong>Save and cancel</strong> when due is clear — the booking is canceled and tagged as an after-visit cancel; refunds (if any) are capped so the retained visit and closing amounts stay.</p>',
  'Bfs_popover_complete_visit_only' => '<p><strong>When to use:</strong> Visit was real but there was little or no meaningful service to bill (loose wire tightened, reset only, “no fault found”).</p><p><strong>What you set:</strong> Same decided charges as cancel-after-visit — visiting charges and optional closing <strong>to be paid</strong>, with company and provider amounts on the visit line and closing line (closing defaults from tiers).</p><p><strong>Payments:</strong> If anything is still due, record payments below until due is zero.</p><p><strong>Action:</strong> Use <strong>Save and complete</strong> when due is clear — the booking is marked completed with this settlement.</p>',
  'Bfs_popover_custom_commission' => '<p><strong>When to use:</strong> You agreed a special company cut for this booking (promotion, dispute, partner deal).</p><p><strong>Example:</strong> Normal math would give company ₹200; you enter ₹120 as fixed company commission for this job only.</p>',
  'Bfs_custom_commission_prefill_hint' => 'Prefilled with your normal tier commission for this booking; change it if you need a different amount. Saving this does not change the booking status.',
  'Bfs_popover_scaled' => '<p><strong>When to use:</strong> The customer did not pay the full booking total — partial collection or bad debt.</p><p><strong>What you enter:</strong> <strong>Amount paid by customer</strong>, and how the unpaid <strong>loss</strong> (booking total minus paid) is recorded as shared between <strong>company</strong> and <strong>provider</strong>. The preview shows total booking amount, computed loss, and those shares.</p><p><strong>Commission:</strong> Company commission still scales with amount collected ÷ booking total.</p><p><strong>Action:</strong> Use <strong>Save and complete</strong> to mark the booking completed with the loss-making tag.</p>',
  'Bfs_preview_loading' => 'Updating…',
