  'Scaled_settlement_explain' => 'Loss = booking total − amount paid by customer. Company loss share + provider loss share must equal that loss (preview updates as you type). Company commission and provider share are calculated on the full booking total; each side’s loss reduces their net share.',
  'Bfs_scaled_loss_split_hint' => 'Company + provider loss shares must equal the loss (booking total minus amount paid). Editing one share adjusts the other.',
