  'Bfs_add_payment_invoice_recovery_hint' => 'Declared loss-making obligation is already met. You can still record extra customer payments up to the full invoice total. Choose who received the cash (company or provider), then split how that payment reduces provider vs company loss — both parts must equal the payment amount.',
  'Bfs_loss_recovery_split_title' => 'Loss recovery split (from this payment)',
  'Bfs_loss_recovery_split_intro' => 'Say who received the cash, then split this payment by how much of it applies to the provider’s remaining loss versus the company’s remaining loss. Each line cannot exceed the max for that side (remaining loss). The two lines must add up to this payment’s amount. Settlement and provider balances use this split (for example, if the company collected the cash, the provider line still drives payables to the provider).',
